L000246	\section{\large{End Matter}}
L000247	
L000248	\section{Appendix A: Spin-orbit-like coupling of light}
L000249	\label{sec:spin-orbit-like-coupling}
L000250	
L000251	The term spin-orbit-like coupling of light~\cite{vuong_electromagnetic_2010, zhao_spin--orbital_2007, marrucci_optical_2006} is used here to denote the intrinsic interdependence between the polarization $\hat{\epsilon}$ and the spatial structure of a classical electromagnetic field describing the light of the tweezer (see Eq.~\ref{eq:E-1st-order}).
L000252	In this context, right- and left-handed circular polarizations are described as spin-like degrees of freedom of the light field, whereas the spatially varying phase and amplitude of the field give rise to orbital-like angular momentum (OAM) associated with the transverse field structure.
L000253	Beyond the paraxial approximation, these two properties are no longer separable, leading to a polarization-dependent spatial field distribution.
L000254	This coupling arises entirely within a classical field description and should be clearly distinguished from coupling between true spin and orbital angular momentum of atomic degrees of freedom.
L000255	
L000256	\section{Appendix B: Light-matter interaction beyond the paraxial approximation}
L000257	\label{sec:light-matter-interaction}
L000258	
L000259	The electric field of the tightly focused tweezer beam near the focal plane is approximated to first order beyond the paraxial limit as~\cite{Novotnoy:2012,Aiello:2015}
L000260	\begin{equation}
L000261	    \mathbf{E}(\mathbf{r},t) \approx {\rm Re}\left[\left(\hat{\boldsymbol{\varepsilon}}-\frac{i\left(\varepsilon_{x}x+\varepsilon_{y}y\right)}{z_{0}}\hat{\mathbf{z}}\right)f(\mathbf{r})e^{i\left(kz-\omega t\right)}\right],\nonumber
L000262	\end{equation}
L000263	where $\hat{\boldsymbol{\varepsilon}} = \varepsilon_x \hat{\mathbf{x}} + \varepsilon_y \hat{\mathbf{y}}$ is the transverse polarization unit vector, $z_0 = \pi w_0^2/\lambda = kw_0^2/2$ is the Rayleigh range, $k$ is the wavenumber and $\omega$ the angular frequency.
L000264	The Gaussian beam mode function is
L000265	\begin{align*}
L000266	f(\mathbf{r}) = E_0\frac{w_{0}}{w(z)}\exp\left(-\frac{\rho^{2}}{w^{2}(z)}+ik\frac{\rho^{2}}{2R(z)}+i\psi(z)\right).
L000267	\end{align*}
L000268	where $\rho=\sqrt{x^2+y^2}$, $w(z)=w_0\sqrt{1+(z/z_0)^2}$ is the beam waist, $R(z)=(z^2+z_0^2)/z$ is the wavefront radius of curvature, and $\psi(z)=-\arctan(z/z_0)$ is the Gouy phase.
L000269	
L000270	The electric field gradients that drive the quadrupole transition $\ket{4S_{1/2},\, m_j}\rightarrow\, \ket{3D_{5/2},\, m_j+\Delta m_j}$ with magnetic quantum number $m_j$ and \mbox{$\Delta m_j=0,\pm1,\pm2$} are~\cite{Weissbluth:2012,Gallagher:2026}
L000271	\begin{align*}
L000272	    (\nabla\mathbf{E})^{(2)}_{\pm2}&=\frac{1}{2}(\partial_x\pm i\partial_y)(E_x\pm iE_y),\\
L000273	    (\nabla\mathbf{E})^{(2)}_{\pm1}&=\frac{1}{2}\left[\mp \partial_z(E_x\pm iE_y)\mp (\partial_x\pm i\partial_y)E_z\right], \textrm{ and}\\
L000274	    (\nabla\mathbf{E})^{(2)}_{0}&=\frac{\sqrt{6}}{2}\partial_z E_z.
L000275	\end{align*}
L000276	The quadrupole Rabi frequency between the ion's ground state $\ket{J_g,m_g}$ and excited state $\ket{J_e,m_e}$ is
L000277	\begin{equation}
L000278	\Omega_{E2,m_g,m_e}=\frac{e a_0^2}{\hbar}Q_{\rm red}C_{J_g,m_g,2,q}^{J_e,m_e}(-1)^q(\tilde{\nabla}\mathbf{E})^{(2)}_{-q},
L000279	\label{eq:rabi freq}
L000280	\end{equation}
L000281	where $Q_{\text{red}}=\frac{\mel{J_e}{|Q^{(2)}|}{J_g}}{\sqrt{2J_e+1}}$ is the reduced quadrupole moment in atomic units~\cite{Kreuter:2005}, $C_{J_g,m_g,2,q}^{J_e,m_e}$ is the Clebsch-Gordon coefficient and $a_0$ is the Bohr radius.
L000282	Here, $\Tilde{\nabla}$ denotes the field gradients rotated to the quantization frame set by the magnetic field $\mathbf{B}$. The resulting spatial dependence of the Rabi frequency calculated from Eq.~\eqref{eq:rabi freq} is compared to experimental measurements in Fig.~\ref{fig:linear_pol}.
